window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[13]={"id":"013","numero":13,"titre":"Certificats médicaux, décès et législation","objectifs":[{"id":"13-1","rang":"A","rubrique":"Définition","titre":"Connaître les règles générales de rédaction d’un certificat médical","contenu":"<p>Le <strong><span class=\"kw-def\">certificat médical</span></strong> est un <span class=\"kw-def\">document écrit rédigé par un médecin</span> à la demande d'un particulier, destiné à <span class=\"kw-def\">constater des faits d'ordre médical</span> de nature à influencer directement ou indirectement ses intérêts (on parle parfois de <span class=\"kw-def\">certificat médico-légal</span>). C'est un document <strong>destiné à faire preuve</strong>.</p>\n      <div class=\"callout callout-info\"><strong>Base légale.</strong> <span class=\"kw-def\">Article 76 du Code de déontologie</span> et <span class=\"kw-def\">article R.4127-76</span> du Code de la santé publique : tout certificat doit être <strong>rédigé lisiblement en langue française et daté</strong>, permettre l'<strong>identification du praticien</strong> et être <strong>signé par lui</strong>.</div>\n\n      <h4 class=\"kw-def\">Ne pas confondre (tombé en annale)</h4>\n      <table >\n        <thead><tr><th>Document</th><th>Remis à</th><th>Secret professionnel</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Certificat médical</span></strong></td><td><span class=\"kw-clinique\">Au patient</span> (en mains propres)</td><td>Préservé</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Rapport de réquisition</span></strong></td><td>Directement à <span class=\"kw-alerte\">l'autorité requérante</span>, jamais au patient</td><td><span class=\"kw-def\">Dérogation légale et obligatoire</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Rapport d'expertise</span></strong></td><td>Directement à <span class=\"kw-alerte\">l'autorité commettante</span>, jamais au patient</td><td><span class=\"kw-def\">Dérogation légale et obligatoire</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Qui peut le rédiger ?</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Tout médecin</span>, y compris les <span class=\"kw-clinique\">internes</span> sous réserve d'être autorisés par le chef de service.</li>\n        <li><strong>Certificat de décès</strong> : médecin <span class=\"kw-def\">thésé et en activité</span> (cas particuliers détaillés à l'obj. dédié).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Mentions à <span class=\"kw-ci\">ne jamais</span> oublier</h4>\n      <ul>\n        <li><strong>Identité du patient</strong> : si inconnu et sans pièce d'identité, formule de prudence <em>« <span class=\"kw-def\">déclarant se nommer</span> »</em> — la victime <span class=\"kw-alerte\">n'est pas obligée</span> de fournir une pièce d'identité.</li>\n        <li><strong>Identité du médecin</strong> : la <span class=\"kw-alerte\">spécialité n'est pas obligatoire</span>.</li>\n        <li><strong>Date exacte de l'examen</strong> : <span class=\"kw-ci\">ne jamais antidater ni postdater</span> ; date du certificat si différente.</li>\n        <li><strong>Signature du médecin</strong> : <span class=\"kw-alerte\">jamais celle du patient ni des parents</span> en cas de mineur (piège QCM).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Structure : allégations / constatations / diagnostic</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Allégations</span></strong> = recueillies à l'interrogatoire = <strong><span class=\"kw-clinique\">subjectives</span></strong> (piège d'annale). Retranscrites <span class=\"kw-clinique\">au conditionnel</span>, formules « d'après les déclarations du patient », idéalement <span class=\"kw-clinique\">en italique</span>. Le médecin <span class=\"kw-ci\">n'affirme jamais la responsabilité d'un tiers</span> ni la réalité des faits.</li>\n        <li><strong><span class=\"kw-def\">Constatations</span></strong> = faits <strong><span class=\"kw-clinique\">objectifs</span></strong> de l'examen. <span class=\"kw-clinique\">Examen clinique obligatoire</span> avant toute délivrance ; le médecin <span class=\"kw-ci\">ne doit jamais interpréter l'origine des blessures</span> (réservé à une partie « Discussion » sur réquisition). Constatations exhaustives, y compris symptômes <span class=\"kw-clinique\">psychologiques</span>.</li>\n        <li><strong><span class=\"kw-def\">Diagnostic</span></strong> : en règle <span class=\"kw-alerte\">ne figure pas</span> sur le certificat (passe par des mains non médicales), sauf cas particuliers.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">À qui le remettre ?</h4>\n      <ul>\n        <li><strong>En mains propres à l'intéressé</strong> : mention <em>« établi à la demande de l'intéressé et remis en mains propres »</em> en conclusion — impératif absolu pour préserver le secret.</li>\n        <li><span class=\"kw-ci\">Jamais</span> à : avocat, police/gendarmerie (hors réquisition), justice (hors réquisition/expertise), parent ou conjoint (utilisation possible en divorce).</li>\n        <li>Dérogations légales : <span class=\"kw-clinique\">mineur → représentant légal</span> ; <span class=\"kw-clinique\">décès → ayants droit</span> ; <span class=\"kw-clinique\">réquisition → autorités de police</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">⚠️ <strong>Certificat de complaisance ou rapport tendancieux = <span class=\"kw-ci\">interdit</span>.</strong> La rédaction engage les responsabilités <span class=\"kw-alerte\">pénale</span>, <span class=\"kw-alerte\">civile</span> et <span class=\"kw-alerte\">disciplinaire</span> du médecin. Les plaintes naissent surtout des <span class=\"kw-etio\">séparations / divorces</span>, en particulier sur des <span class=\"kw-etio\">examens d'enfants</span>.</div>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège.</strong> Sur un certificat de coups et blessures, <span class=\"kw-ci\">ne jamais écrire les ATCD sans lien avec le contexte</span> (violation du secret). Forme : papier libre / ordonnance / formulaire pré-imprimé, écriture lisible, style clair, en français.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 7 — Dossier médical, information, secret médical · 47 — Suivi d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":7},{"id":"13-2","rang":"A","rubrique":"Définition","titre":"Connaître les différents types de certificats médicaux obligatoires","contenu":"<p>Un certificat est <strong><span class=\"kw-def\">obligatoire</span></strong> à chaque fois que sa rédaction est <strong>prévue par un texte</strong>. En dehors de ces cas, le certificat est <span class=\"kw-def\">facultatif</span>.</p>\n\n      <h4 class=\"kw-def\">Certificats obligatoires (tombé en annale)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Naissance</span>, <span class=\"kw-clinique\">Décès</span>, <span class=\"kw-clinique\">Grossesse</span>, <span class=\"kw-clinique\">IMG et IVG</span>.</li>\n        <li>Législation sociale : <span class=\"kw-clinique\">accident du travail</span>, <span class=\"kw-clinique\">maladie professionnelle</span>.</li>\n        <li><span class=\"kw-clinique\">Soins psychiatriques sous contrainte</span>.</li>\n        <li><span class=\"kw-clinique\">Vaccination</span> ; <span class=\"kw-clinique\">suivi de la santé du mineur</span> (certificats des 1ʳᵉˢ années de vie).</li>\n        <li>Certificat de <span class=\"kw-clinique\">« coups et blessures »</span> — considéré obligatoire car nécessaire au patient pour faire valoir ses droits.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Certificats facultatifs</h4>\n      <ul>\n        <li>Le médecin « doit, sans céder à aucune demande abusive, <strong>faciliter l'obtention d'avantages sociaux</strong> » auxquels l'état du patient donne droit.</li>\n        <li>Il peut <strong>refuser</strong> un certificat facultatif selon sa libre appréciation, en <span class=\"kw-clinique\">informant le patient des raisons</span>.</li>\n        <li><span class=\"kw-ci\">Délivrance d'un certificat de complaisance interdite.</span></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Distracteurs cochés FAUX en annale.</strong> Le <span class=\"kw-alerte\">certificat prénuptial</span> et le <span class=\"kw-alerte\">certificat d'aptitude sportive</span> ne sont <strong>pas</strong> des certificats obligatoires. (Rang C : pour certaines fédérations « à risques », la non-contre-indication exige un médecin du sport ou agréé.)</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — Suivi d'un nourrisson, d’un enfant, d'un adolescent · 15 — Soins psychiatriques sans consentement · 7 — Dossier médical, information, secret médical</em></p>","frequence":4},{"id":"13-3","rang":"B","rubrique":"Définition","titre":"Définir les coups et blessures volontaires et involontaires et l’incapacité temporaire totale (ITT)","contenu":"<p><strong><span class=\"kw-def\">Volontaire</span> = agression</strong> ; <strong><span class=\"kw-def\">involontaire</span> = accident</strong>. Le médecin <span class=\"kw-ci\">ne se prononce jamais</span> sur le caractère volontaire ou involontaire des blessures (établi par l'enquête et la justice).</p>\n\n      <h4 class=\"kw-def\">ITT au sens du Code pénal</h4>\n      <ul>\n        <li>Définition : <strong><span class=\"kw-def\">perte majeure d'autonomie</span></strong> = impossibilité d'effectuer seul les <span class=\"kw-clinique\">actes ordinaires et essentiels de la vie quotidienne</span> (se laver, s'habiller, s'alimenter, se mouvoir…).</li>\n        <li><span class=\"kw-alerte\">Aucun lien avec le travail professionnel</span> malgré l'ambiguïté du terme → on peut la délivrer à un <span class=\"kw-clinique\">enfant</span>, un retraité ou un chômeur.</li>\n        <li>Le <strong><span class=\"kw-clinique\">retentissement psychologique</span></strong> fait partie intégrante de l'ITT ; elle peut être <span class=\"kw-clinique\">strictement psychologique</span> si elle entraîne une perte majeure d'autonomie.</li>\n        <li><span class=\"kw-alerte\">Ne tient PAS compte</span> des difficultés à travailler ni des difficultés pour une activité de loisir (distracteurs).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Conséquences judiciaires (tribunal + peine selon la durée)</h4>\n      <table >\n        <thead><tr><th>Contexte</th><th>Durée ITT</th><th>Qualification → juridiction</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"2\"><strong>Agression</strong> (volontaire)</td><td><span class=\"kw-chiffre\">&gt; 8 jours</span></td><td>Délit → <span class=\"kw-def\">tribunal correctionnel</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">≤ 8 jours</span> ou <span class=\"kw-chiffre\">= 0 jour</span></td><td>Contravention → <span class=\"kw-def\">tribunal de police</span></td></tr>\n          <tr><td rowspan=\"2\"><strong>Accident</strong> (involontaire)</td><td><span class=\"kw-chiffre\">&gt; 3 mois</span></td><td>Tribunal correctionnel</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&lt; 3 mois</span></td><td>Tribunal de police</td></tr>\n        </tbody>\n      </table>\n\n      <ul>\n        <li>L'ITT permet au <span class=\"kw-clinique\">magistrat</span> de connaître les répercussions sur l'état de santé, mais il <span class=\"kw-alerte\">n'est jamais lié</span> à cet avis (il peut <span class=\"kw-def\">correctionnaliser</span> : récidive, circonstances aggravantes liées à la vulnérabilité de la victime — <span class=\"kw-etio\">mineur &lt; 15 ans</span>, personne âgée, infirmité, <span class=\"kw-etio\">femme enceinte</span>).</li>\n        <li>Pénal : le certificat concerne surtout <strong>l'auteur</strong>. Civil : la <span class=\"kw-clinique\">charge de la preuve incombe à la victime</span> → exhaustivité du <span class=\"kw-def\">certificat médical initial (CMI)</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Pièges.</strong> Il <span class=\"kw-alerte\">n'existe aucun délai réglementaire</span> entre les blessures et la consultation pour évaluer l'ITT. Préférer écrire « <span class=\"kw-def\">ITT au sens du Code pénal</span> » pour éviter la confusion avec le droit civil.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles</em></p>","frequence":7},{"id":"13-4","rang":"B","rubrique":"Définition","titre":"Connaître et identifier les lésions traumatiques élémentaires de médecine légale et savoir les différencier","contenu":"<p>Les lésions traumatiques élémentaires se classent selon le <strong><span class=\"kw-def\">mécanisme</span></strong> (contondant / tranchant) et la profondeur de l'atteinte cutanée.</p>\n\n      <table >\n        <thead><tr><th>Lésion</th><th>Mécanisme</th><th>Aspect</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Érythème</span></strong></td><td>Traumatisme contondant plat, peu violent (gifle)</td><td>Rougeur sans relief</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Érosions superficielles</span></strong></td><td>Élément pointu déplacé tangentiellement (griffure) ; dermabrasion = frottement (chute)</td><td>Linéaires / arciformes ; reproduit la forme du contact</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Contusion</span></strong> (fermée)</td><td>Mécanisme contondant mousse (matraque, mur, mains)</td><td><span class=\"kw-clinique\">Ecchymose</span> (sang extravasé coagulé) ; <span class=\"kw-clinique\">hématome</span> (collection dans une cavité néoformée) ; écrasement / broiement</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Plaie nette / simple</span></strong></td><td>Instrument <span class=\"kw-clinique\">tranchant</span> coupant ou piquant</td><td>Berges nettes, <strong>pas de pont tissulaire</strong></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Plaie contuse</span></strong></td><td>Traumatisme contondant violent ; peau écrasée sur un plan osseux (arcade, lèvres)</td><td>Bords irréguliers, <strong>ponts tissulaires</strong>, décollement sous-cutané</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Morsure</span></strong></td><td>Empreinte des arcades dentaires</td><td>2 lignes courbes à concavité opposée, ecchymose centrale</td></tr>\n          <tr><td>Fracture / entorse / luxation</td><td>« Solution de continuité » osseuse ; déplacement articulaire</td><td>—</td></tr>\n          <tr><td><span class=\"kw-clinique\">Brûlure</span> / <span class=\"kw-clinique\">gelure</span></td><td>Thermique, chimique, électrique, nucléaire, ondes / froid intense</td><td>—</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Datation indicative de l'ecchymose (dégradation de l'<span class=\"kw-bio\">hémoglobine</span>)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Violacée noirâtre</span> : <span class=\"kw-chiffre\">1 à 3 jours</span> → lésion <strong>récente</strong> (tombé en annale).</li>\n        <li><span class=\"kw-clinique\">Verdâtre</span> : <span class=\"kw-chiffre\">5 à 6 jours</span> → lésion <strong>semi-récente</strong>.</li>\n        <li><span class=\"kw-clinique\">Brun jaunâtre</span> : <span class=\"kw-chiffre\">10 à 15 jours</span> → lésion <strong>ancienne</strong> (tombé en annale).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Diagnostics différentiels de la contusion</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Ecchymoses spontanées</span> : troubles de l'hémostase, syndromes infectieux, asphyxies.</li>\n        <li><span class=\"kw-etio\">Lividités cadavériques</span>, taches mongoloïdes, certaines lésions dermatologiques.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège.</strong> Ces chiffres de datation sont <span class=\"kw-alerte\">uniquement indicatifs</span> : on <span class=\"kw-ci\">ne demande pas au médecin non légiste de dater une lésion</span> dans un certificat — décrire la <strong>couleur</strong>, pas l'âge.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles</em></p>","frequence":0},{"id":"13-5","rang":"B","rubrique":"Contenu multimédia","titre":"Exemple des lésions élémentaires (ecchymoses, hématomes plaies...)","contenu":"<p>Objectif d'<strong>iconographie</strong> : savoir reconnaître et <strong>différencier</strong> les lésions élémentaires sur un cliché. Les paires « pièges » à distinguer au coup d'œil :</p>\n\n      <table >\n        <thead><tr><th>À distinguer</th><th>Critère discriminant</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Ecchymose</span></strong> vs <strong><span class=\"kw-clinique\">hématome</span></strong></td><td>Ecchymose = sang <span class=\"kw-clinique\">extravasé et coagulé</span> imprégnant les tissus ; hématome = <span class=\"kw-clinique\">collection</span> de sang dans une cavité néoformée (relief)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Plaie nette</span></strong> vs <strong><span class=\"kw-clinique\">plaie contuse</span></strong></td><td>Nette = berges régulières, <strong>pas de pont tissulaire</strong> (<span class=\"kw-clinique\">instrument tranchant</span>) ; contuse = bords irréguliers, <strong>ponts tissulaires</strong> + décollement (<span class=\"kw-clinique\">mécanisme contondant</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Érosion</span></strong> vs <strong><span class=\"kw-clinique\">plaie</span></strong></td><td>Érosion = abrasion <span class=\"kw-clinique\">superficielle</span> de l'<span class=\"kw-clinique\">épiderme</span> ; plaie = « solution de continuité » traversant le <span class=\"kw-clinique\">derme</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Morsure</span></strong></td><td>2 arcs ecchymotiques à <strong>concavité opposée</strong> + ecchymose centrale</td></tr>\n        </tbody>\n      </table>\n\n      <ul>\n        <li>La <strong>datation par la couleur</strong> de l'<span class=\"kw-clinique\">ecchymose</span> (<span class=\"kw-clinique\">violacé</span> → <span class=\"kw-clinique\">verdâtre</span> → <span class=\"kw-clinique\">brun jaunâtre</span>) reste <span class=\"kw-alerte\">indicative</span> : décrire, ne pas dater.</li>\n        <li>Possibilité de <strong>clichés photographiques</strong> pour documenter les lésions (tombé en annale) ; lésions <span class=\"kw-clinique\">dentaires</span> souvent oubliées.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📷 Les 5 images du dossier source sont des captures du <span class=\"kw-def\">Cerfa CertDC</span> (volet administratif / médical), retranscrites à l'objectif « certificat de décès ». Les photos cliniques de lésions (Collège) restent à intégrer ultérieurement — la sémiologie descriptive ci-dessus suffit pour réviser.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles</em></p>","frequence":1},{"id":"13-6","rang":"A","rubrique":"Epidémiologie","titre":"Connaître la prévalence des violences faites aux femmes et plus particulièrement des violences conjugales","contenu":"<h4 class=\"kw-def\">Violences au sein du couple — chiffres clés</h4>\n      <ul>\n        <li>Dans le monde, <strong><span class=\"kw-chiffre\">1 femme sur 4</span></strong> est victime de violence <span class=\"kw-clinique\">physique ou sexuelle</span> par un partenaire intime.</li>\n        <li>En Europe : <span class=\"kw-chiffre\">22 %</span> des femmes victimes de violences physiques/sexuelles et <span class=\"kw-chiffre\">43 %</span> de violences <span class=\"kw-clinique\">psychologiques</span> par un partenaire intime ; <span class=\"kw-clinique\">cyberviolence</span> <span class=\"kw-chiffre\">1 femme sur 10</span> (&gt;<span class=\"kw-chiffre\"> 15 ans</span>).</li>\n        <li>France (enquête <span class=\"kw-def\">VIRAGE</span>) : sur <span class=\"kw-chiffre\">12 mois</span>, <span class=\"kw-chiffre\">1 %</span> de violences physiques par un partenaire, <span class=\"kw-chiffre\">20 %</span> psychologiques, <span class=\"kw-chiffre\">0,1 %</span> sexuelles. Espace public : <span class=\"kw-chiffre\">25 %</span> des femmes vs <span class=\"kw-chiffre\">14 %</span> des hommes.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Gravité et recours</h4>\n      <ul>\n        <li><strong><span class=\"kw-chiffre\">82 %</span></strong> des morts en contexte de <span class=\"kw-alerte\">violence conjugale</span> sont des femmes ; <span class=\"kw-chiffre\">47 %</span> des viols sont commis par le partenaire ou l'ex-partenaire.</li>\n        <li>Sous-recours majeur : seules <span class=\"kw-chiffre\">18 %</span> des victimes déposent plainte, <span class=\"kw-chiffre\">24 %</span> consultent un médecin, et <span class=\"kw-chiffre\">52 %</span> ne font <strong>aucune démarche</strong>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Morts violentes (repère général OMS)</h4>\n      <ul>\n        <li>Les <span class=\"kw-clinique\">morts violentes</span> (homicides, suicides) touchent surtout les <span class=\"kw-clinique\">hommes</span> ; suicide maximal après <span class=\"kw-chiffre\">60 ans</span>, homicide entre <span class=\"kw-chiffre\">15 et 29 ans</span> ; 2× plus fréquentes dans les pays à faible revenu.</li>\n      </ul>\n\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Médecine légale et médecine du travail (item « Violences et santé »).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles</em></p>","frequence":0},{"id":"13-7","rang":"A","rubrique":"Définition","titre":"Connaître les particularités des violences faites aux femmes et plus particulièrement des violences conjugales","contenu":"<p>La <strong><span class=\"kw-def\">violence</span></strong> (OMS) = usage délibéré, ou menace d'usage, de la <span class=\"kw-clinique\">force physique</span> ou de la <span class=\"kw-clinique\">puissance</span> contre soi, autrui ou un groupe, entraînant ou risquant d'entraîner un traumatisme, un décès ou un dommage. Elle peut être <span class=\"kw-clinique\">physique, psychique, sexuelle, économique ou administrative</span>.</p>\n\n      <h4 class=\"kw-def\">Typologie</h4>\n      <ul>\n        <li><span class=\"kw-def\">Auto-infligée</span> / <span class=\"kw-def\">interpersonnelle</span> (scolaire, travail, <strong>domestique</strong>) / <span class=\"kw-def\">collective</span>.</li>\n        <li>La <span class=\"kw-def\">violence domestique</span> inclut la <strong>violence conjugale</strong> + maltraitances à enfant et personne âgée.</li>\n        <li><span class=\"kw-def\">Violence au sein du couple</span> = toute violence d'un partenaire intime, relation présente ou passée (marié, pacsé, concubinage, union libre). C'est une <span class=\"kw-alerte\">infraction punie par la loi</span>, aux peines <strong>aggravées</strong> quand l'auteur est conjoint/concubin/partenaire de PACS.</li>\n        <li>Les <span class=\"kw-def\">violences faites aux femmes</span> sont des violences <strong>systémiques liées au genre</strong> (ONU) ; les violences conjugales en font partie (fréquence, gravité et conséquences majorées chez les femmes).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Spécificités de la violence domestique</h4>\n      <ul>\n        <li>Se déroule dans l'<span class=\"kw-clinique\">intimité</span> (non public).</li>\n        <li>Généralement <span class=\"kw-clinique\">chronique</span> et tend à <span class=\"kw-alerte\">s'aggraver</span> au cours du temps.</li>\n        <li><span class=\"kw-clinique\">Lien émotionnel fort</span> entre victime et auteur.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Mécanismes (typologie de Johnson) et cycle de la violence</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Terrorisme intime</span></strong> : violence coercitive de contrôle (auteurs surtout des hommes) — majoritaire en milieu de soin.</li>\n        <li><span class=\"kw-def\">Résistance violente</span> ; <span class=\"kw-def\">violence situationnelle</span> (la plus fréquente en population générale) ; <span class=\"kw-def\">contrôle mutuel</span> (rare).</li>\n        <li><strong><span class=\"kw-def\">Cycle de la violence</span></strong> (Walker, 1979) : <span class=\"kw-clinique\">tension</span> → <span class=\"kw-clinique\">crise / agression</span> → <span class=\"kw-clinique\">justification</span> (culpabilisation de la victime) → <span class=\"kw-clinique\">« lune de miel »</span>.</li>\n        <li>L'<strong><span class=\"kw-def\">emprise</span></strong> (ascendance intellectuelle, morale ou économique) crée une <span class=\"kw-alerte\">contrainte morale</span> rendant la sortie de la situation impossible.</li>\n      </ul>\n\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Médecine légale et médecine du travail (item « Violences et santé »).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles</em></p>","frequence":0},{"id":"13-8","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier les situations de vulnérabilités, particulièrement concernant les violences conjugales","contenu":"<p>La <strong><span class=\"kw-def\">vulnérabilité</span></strong> (Code pénal) = incapacité d'une personne à <strong>se protéger</strong> en raison de son <span class=\"kw-clinique\">âge</span>, d'une <span class=\"kw-clinique\">maladie</span>, d'une <span class=\"kw-clinique\">infirmité</span>, d'une <span class=\"kw-clinique\">déficience physique ou psychique</span> ou d'un <span class=\"kw-clinique\">état de grossesse</span>. Pas de critère préétabli ; elle peut tenir à une pathologie, un traitement, une <span class=\"kw-etio\">précarité socio-économique</span> (isolement, migration) ou une <span class=\"kw-etio\">situation d'emprise</span>.</p>\n\n      <h4 class=\"kw-def\">Dépistage (recommandation HAS)</h4>\n      <ul>\n        <li><strong>Dépistage systématique</strong> : « je pose la question à tous mes patients », quel que soit le motif et <span class=\"kw-alerte\">même sans signe d'alerte</span>.</li>\n        <li><span class=\"kw-clinique\">Entretien en dualité</span> (seul à seul) + examen clinique complet avec accord du patient.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Signes d'alerte à rechercher</h4>\n      <table >\n        <thead><tr><th>Chez la victime</th><th>Chez le conjoint / les enfants</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Lésions traumatiques répétées</span> sur zones de prise/défense, sans explication cohérente ; plaintes multiples sans substrat ; mauvaise observance ; retards répétés ; comportement <span class=\"kw-clinique\">craintif</span>, isolement, refus d'être examinée</td>\n            <td><strong>Conjoint</strong> : accompagnant trop impliqué qui répond à sa place, minimise, propos disqualifiants.<br><strong>Enfants</strong> : rupture du comportement, repli ou hyperactivité, troubles du sommeil/alimentation, rupture scolaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">🚨 <strong>Évaluer la dangerosité</strong> (risque de passage à l'acte <span class=\"kw-alerte\">homicide ou suicide</span>) : <span class=\"kw-clinique\">armes au domicile</span>, <span class=\"kw-clinique\">menaces de mort</span>, <span class=\"kw-clinique\">tentative de strangulation</span>, addiction, jalousie/contrôle, séparation récente, grossesse/post-partum, enfants témoins.</div>\n\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Médecine légale et médecine du travail (item « Violences et santé »).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles · 57 — Maltraitance, enfant en danger</em></p>","frequence":0},{"id":"13-9","rang":"B","rubrique":"Définition","titre":"Connaître la définition d’un signalement judiciaire","contenu":"<p>Le <strong><span class=\"kw-def\">signalement</span></strong> consiste à porter à la connaissance des <span class=\"kw-clinique\">autorités judiciaires ou administratives</span> des faits dans le but de <strong>protéger une <span class=\"kw-clinique\">victime</span></strong>.</p>\n\n      <h4 class=\"kw-def\">À qui signaler ?</h4>\n      <ul>\n        <li>Autorité <span class=\"kw-clinique\">judiciaire</span> : <strong><span class=\"kw-def\">Procureur de la République</span></strong>.</li>\n        <li>Autorité <span class=\"kw-clinique\">administrative</span> (<span class=\"kw-clinique\">mineurs</span>) : <span class=\"kw-def\">conseil départemental</span>, <strong><span class=\"kw-def\">CRIP</span></strong> (cellule de recueil des informations préoccupantes relatives aux <span class=\"kw-clinique\">mineurs en danger</span>).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Règles de rédaction</h4>\n      <ul>\n        <li>Doit être <span class=\"kw-clinique\">objectif</span>.</li>\n        <li><span class=\"kw-ci\">Ne jamais mettre un tiers en cause de manière nominative</span> : on <strong>signale le <span class=\"kw-clinique\">danger</span></strong>, jamais l'<span class=\"kw-etio\">auteur supposé</span>.</li>\n        <li>Le médecin <span class=\"kw-alerte\">ne peut pas être poursuivi</span> pour un signalement s'il a respecté les textes (sauf mauvaise foi établie).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>À ne pas confondre avec la réquisition.</strong> La <span class=\"kw-def\">réquisition judiciaire</span> est une <strong><span class=\"kw-def\">injonction</span></strong> d'un <span class=\"kw-clinique\">officier de police judiciaire</span> ou d'un <span class=\"kw-clinique\">magistrat</span> (obligatoire) ; le signalement est, lui, une <span class=\"kw-def\">dérogation au secret</span> le plus souvent <strong>facultative</strong> (voir obj. suivant).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 57 — Maltraitance, enfant en danger · 7 — Dossier médical, information, secret médical · 15 — Soins psychiatriques sans consentement</em></p>","frequence":0},{"id":"13-10","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir quelles situations imposent un signalement judiciaire, particulièrement concernant les violences conjugales","contenu":"<p>Le signalement est une <strong><span class=\"kw-def\">dérogation légale facultative</span></strong> au secret médical : le médecin n'a pas l'obligation de signaler, mais il a l'<strong>obligation de protéger</strong> son patient. Le signalement devient <span class=\"kw-alerte\">obligatoire</span> lorsqu'il est le <strong>seul moyen de protéger</strong> la victime.</p>\n\n      <h4 class=\"kw-def\">Procédure (accord de la victime)</h4>\n      <ul>\n        <li>Le médecin doit <strong>s'efforcer d'obtenir l'accord</strong> de la victime <span class=\"kw-clinique\">majeure</span>.</li>\n        <li>En cas d'impossibilité, il l'<strong>informe</strong> du signalement adressé au <span class=\"kw-def\">procureur de la République</span> si : <span class=\"kw-clinique\">mineur</span>, <span class=\"kw-clinique\">personne vulnérable</span>, ou <span class=\"kw-alerte\">danger imminent / menace vitale</span>.</li>\n        <li><span class=\"kw-def\">Réforme de l'article 226-14</span> (loi du 30/07/2020) : possibilité de signaler au procureur, même <strong>sans accord</strong> de la victime majeure, en cas de <span class=\"kw-alerte\">danger immédiat</span> et d'<span class=\"kw-alerte\">emprise</span>.</li>\n        <li>📎 Outil de repérage : <span class=\"kw-def\">vade-mecum du CNOM</span> (Conseil National de l'Ordre des Médecins) « <em>Signalement des violences conjugales – danger</em> » — grilles de questions pour <strong>caractériser le danger immédiat</strong> et l'<strong>emprise</strong> chez la victime majeure.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Situations relevant d'un signalement</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Maltraitance</span> d'un mineur ou d'une personne vulnérable (en danger ou en risque de l'être).</li>\n        <li><strong>Violences conjugales</strong> : si <span class=\"kw-alerte\">menace vitale</span> ou si la victime n'est pas en mesure de se protéger.</li>\n        <li><span class=\"kw-clinique\">Détention d'arme</span> ou intention d'en acquérir.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">🚨 <strong>Urgence.</strong> Évaluer le <span class=\"kw-alerte\">risque homicide/suicide</span> avant tout ; la mise en sécurité (hospitalisation, signalement, plan de sécurité) prime sur la temporalité administrative.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 57 — Maltraitance, enfant en danger · 15 — Soins psychiatriques sans consentement · 12 — Violences sexuelles</em></p>","frequence":0},{"id":"13-11","rang":"B","rubrique":"Diagnostic positif","titre":"Identifier le retentissement psychologique des violences et plus particulièrement dans les violences conjugales","contenu":"<p>Le <strong><span class=\"kw-clinique\">retentissement psychologique</span></strong> est une composante <strong>intégrante de l'<span class=\"kw-def\">ITT</span></strong> au sens du Code pénal : l'ITT peut être <span class=\"kw-alerte\">strictement psychologique</span> dès lors qu'elle entraîne une <span class=\"kw-clinique\">perte majeure d'autonomie</span>.</p>\n\n      <h4 class=\"kw-def\">Conséquences psychiques à rechercher</h4>\n      <table >\n        <thead><tr><th>Domaine</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Thymique / suicidaire</strong></td><td><span class=\"kw-clinique\">Syndrome dépressif</span>, idées et <span class=\"kw-alerte\">tentatives de suicide</span>, automutilations</td></tr>\n          <tr><td><strong>Traumatique</strong></td><td><span class=\"kw-clinique\">État de stress post-traumatique</span> : hypervigilance, troubles du sommeil, cauchemars, modification du comportement</td></tr>\n          <tr><td><strong>Émotionnel</strong></td><td>Colère, honte, <span class=\"kw-clinique\">culpabilité</span>, humiliation, sentiment d'impuissance, autodévalorisation</td></tr>\n          <tr><td><strong>Anxieux</strong></td><td>Anxiété, attaques de <span class=\"kw-clinique\">panique</span>, manifestations phobiques</td></tr>\n          <tr><td><strong>Fonctions instinctuelles</strong></td><td>Troubles du sommeil, troubles alimentaires (anorexie/boulimie), troubles cognitifs (concentration, mémoire), <span class=\"kw-clinique\">addictions</span></td></tr>\n        </tbody>\n      </table>\n\n      <ul>\n        <li>Un <strong><span class=\"kw-clinique\">ESPT</span></strong> est retrouvé chez <span class=\"kw-chiffre\">&gt; 50 %</span> des femmes consultant dans ce contexte, surtout après <span class=\"kw-clinique\">violences sexuelles</span>.</li>\n        <li>Toujours explorer le <span class=\"kw-alerte\">risque de passage à l'acte autoagressif</span>.</li>\n        <li>Conséquences chez l'<span class=\"kw-clinique\">enfant témoin</span> : multiples et non spécifiques (<span class=\"kw-clinique\">rupture comportementale</span>, <span class=\"kw-clinique\">scolaire</span>, <span class=\"kw-clinique\">troubles du sommeil</span>, <span class=\"kw-clinique\">plaintes somatiques</span>).</li>\n      </ul>\n\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Médecine légale et médecine du travail (item « Violences et santé »).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles</em></p>","frequence":0},{"id":"13-12","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la mort","contenu":"<p>La <strong><span class=\"kw-def\">mort</span></strong> = perte définitive, par une entité vivante, des <span class=\"kw-def\">propriétés de la vie</span>, entraînant sa destruction.</p>\n\n      <h4 class=\"kw-def\">Diagnostic de la mort = diagnostic médical</h4>\n      <ul>\n        <li>Repose sur la constatation des <strong><span class=\"kw-def\">signes négatifs de la vie</span></strong> (qui <span class=\"kw-alerte\">ne suffisent pas seuls</span>, notamment dans certaines intoxications) <strong>et</strong> des <strong><span class=\"kw-def\">signes positifs de la mort</span></strong>.</li>\n        <li>La constatation du caractère <strong>réel et constant</strong> de la mort est <span class=\"kw-clinique\">indispensable</span> à l'établissement du certificat de décès (ex. <span class=\"kw-clinique\">tache verte abdominale</span>, lividités).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Délai post-mortem</h4>\n      <ul>\n        <li>Délai entre la survenue du décès et le diagnostic de la mort ; estimé par l'étude médico-légale précoce (<span class=\"kw-clinique\">refroidissement</span>, <span class=\"kw-clinique\">lividités</span>, <span class=\"kw-clinique\">rigidité</span>) puis par l'<span class=\"kw-clinique\">entomologie</span> chez le corps putréfié.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Comptés FAUX en QCM</strong> pour affirmer la mort : <span class=\"kw-alerte\">hypothermie à 32 °C</span>, <span class=\"kw-alerte\">absence de pouls radial</span>, <span class=\"kw-alerte\">absence de réaction à la douleur</span> (ce ne sont que des signes négatifs). La <span class=\"kw-alerte\">formule dentaire n'aide pas</span> à dater le décès (mais sert à l'identification).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 345 — Malaise grave du nourrisson, mort subite</em></p>","frequence":0},{"id":"13-13","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une mort suspecte, inhabituelle, violente","contenu":"<p>Ces morts sont les principales situations imposant de <strong>cocher l'<span class=\"kw-def\">obstacle médico-légal à l'inhumation</span></strong> — la « porte d'entrée médicale » vers la <span class=\"kw-alerte\">judiciarisation pénale</span> du décès.</p>\n\n      <table >\n        <thead><tr><th>Type de mort</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Mort violente</span></strong></td><td>Résulte d'un <span class=\"kw-etio\">agent extérieur</span> (physique ou toxique) en circonstances <span class=\"kw-alerte\">criminelles, suicidaires ou accidentelles</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mort suspecte</span></strong></td><td>Impossible d'<strong>exclure l'intervention d'un tiers</strong></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mort subite</span></strong> inhabituelle / inexpliquée</td><td>Sauf <span class=\"kw-clinique\">MIN</span> (mort inattendue du nourrisson)</td></tr>\n          <tr><td>Mort posant un problème de <span class=\"kw-clinique\">responsabilité médicale</span></td><td>—</td></tr>\n          <tr><td><span class=\"kw-clinique\">Corps non identifié</span></td><td>Ex. putréfaction, carbonisation</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Conséquences de l'obstacle médico-légal</h4>\n      <ul>\n        <li><strong>Obligation</strong> pour le médecin de se mettre en rapport avec le <span class=\"kw-def\">procureur de la République</span> ou les services de police/gendarmerie.</li>\n        <li><span class=\"kw-clinique\">Suspension</span> de toutes les opérations funéraires ; corps <strong>indisponible</strong> (non présenté aux proches) avant levée de l'obstacle ou délivrance du permis d'inhumer par le procureur.</li>\n        <li><strong>Possibilité</strong> de réquisition d'un médecin pour une <span class=\"kw-clinique\">levée de corps</span> ou une <span class=\"kw-clinique\">autopsie médico-légale</span> (non systématiques).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Pièges (comptés FAUX).</strong> La suspicion de <span class=\"kw-alerte\">maladie à prion</span> n'est <strong>pas</strong> un obstacle médico-légal ; la <span class=\"kw-alerte\">MIN</span> n'en est pas un non plus (sauf refus parental d'autopsie). Pour la MIN, il est recommandé de <strong>ne pas cocher</strong> l'obstacle.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 345 — Malaise grave du nourrisson, mort subite · 12 — Violences sexuelles</em></p>","frequence":2},{"id":"13-14","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer la mort","contenu":"<h4 class=\"kw-def\">Signes négatifs de la vie (×3 — ne suffisent pas)</h4>\n      <ul>\n        <li>Arrêt des fonctions cérébrales : abolition de la <span class=\"kw-clinique\">conscience</span>, <span class=\"kw-clinique\">aréflexie</span>, <span class=\"kw-clinique\">mydriase</span>.</li>\n        <li>Arrêt de l'activité <span class=\"kw-clinique\">respiratoire</span> ; arrêt de l'activité <span class=\"kw-clinique\">cardiovasculaire</span> (pas de pouls sur les troncs artériels).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Signes positifs précoces (datation du décès)</h4>\n      <table >\n        <thead><tr><th>Signe</th><th>Mécanisme</th><th>Chronologie / intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Refroidissement</span></strong> cadavérique</td><td>Plateau initial puis perte de <span class=\"kw-chiffre\">1 °C / heure</span> jusqu'à l'équilibre</td><td>Estimation du délai post-mortem</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Lividités</span></strong></td><td>Autolyse + <span class=\"kw-clinique\">transsudation du sang</span> dans les zones déclives (pesanteur)</td><td>Apparition <span class=\"kw-chiffre\">45 min</span> ; max <span class=\"kw-chiffre\">9h30</span> ; disparition incomplète après retournement <span class=\"kw-chiffre\">11h</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Rigidité</span></strong></td><td>Liaisons <span class=\"kw-clinique\">actine-myosine</span> irréversibles (chute de l'ATP), muscles striés et lisses ; débute aux <span class=\"kw-clinique\">masséters</span> (progression descendante)</td><td>Début <span class=\"kw-chiffre\">3h</span> ; max <span class=\"kw-chiffre\">8h</span> ; disparition <span class=\"kw-chiffre\">76h</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Signes positifs tardifs</h4>\n      <ul>\n        <li>Décomposition / <span class=\"kw-clinique\">putréfaction</span> : <span class=\"kw-clinique\">tache verte abdominale</span> <span class=\"kw-chiffre\">24-48h</span> → circulation posthume <span class=\"kw-chiffre\">1 semaine</span> → phlyctènes <span class=\"kw-chiffre\">1-2 semaines</span> → <span class=\"kw-clinique\">squelettisation</span> <span class=\"kw-chiffre\">12 à 18 mois</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ Ces délais comportent d'<span class=\"kw-alerte\">importantes variations</span> (température, cause du décès) → estimation, jamais une datation précise. Lividités <span class=\"kw-alerte\">rouge vif</span> = intoxication au <span class=\"kw-etio\">CO</span> (piège annale) ; lividités pâles = spoliation sanguine ; topographie incompatible = <strong>déplacement du corps</strong>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 345 — Malaise grave du nourrisson, mort subite</em></p>","frequence":6},{"id":"13-15","rang":"B","rubrique":"Contenu multimédia","titre":"Exemple de lividité, rigidité","contenu":"<p>Objectif d'<strong>iconographie</strong> : reconnaître les deux <span class=\"kw-def\">signes positifs précoces de la mort</span> et les <strong>dater</strong>.</p>\n\n      <table >\n        <thead><tr><th>Signe</th><th>Aspect</th><th>Début</th><th>Maximum</th><th>Disparition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Lividités</span></strong></td><td>Taches <span class=\"kw-clinique\">rouge violacé</span> des zones <strong>déclives</strong>, absentes aux zones d'appui</td><td><span class=\"kw-chiffre\">45 min</span></td><td><span class=\"kw-chiffre\">9h30</span></td><td>Incomplète après retournement à <span class=\"kw-chiffre\">11h</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Rigidité</span></strong></td><td>Contraction des muscles, débute aux <span class=\"kw-clinique\">masséters</span>, progression descendante</td><td><span class=\"kw-chiffre\">3h</span></td><td><span class=\"kw-chiffre\">8h</span></td><td><span class=\"kw-chiffre\">76h</span></td></tr>\n        </tbody>\n      </table>\n\n      <ul>\n        <li>Valeur médico-légale : <strong><span class=\"kw-def\">estimation du délai post-mortem</span></strong> et détection d'un <span class=\"kw-clinique\">déplacement du corps</span> (lividités incompatibles avec la position).</li>\n        <li>Couleur des lividités orientant la cause : <span class=\"kw-alerte\">rouge vif</span> = intoxication au <span class=\"kw-etio\">CO</span> ; <span class=\"kw-clinique\">pâles et peu étendues</span> = <span class=\"kw-etio\">spoliation sanguine</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📷 Photos cliniques de lividité/rigidité (Collège) à intégrer ultérieurement ; la description chronologique ci-dessus suffit pour réviser l'objectif.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 345 — Malaise grave du nourrisson, mort subite</em></p>","frequence":0},{"id":"13-16","rang":"A","rubrique":"Définition","titre":"Connaître les règles générales de rédaction d'un certificat de décès","contenu":"<p>Le <strong><span class=\"kw-def\">certificat de décès</span></strong> est un certificat <strong>obligatoire</strong>. La <span class=\"kw-def\">certification électronique</span> (<span class=\"kw-def\">CertDC</span> / CertDC Mobil) est la règle ; le format <span class=\"kw-clinique\">papier en 4 exemplaires</span> reste exceptionnel (décès hors établissement de santé ou EHPAD, ou raisons techniques).</p>\n\n      <h4 class=\"kw-def\">Qui peut l'établir ? (tombé en annale)</h4>\n      <ul>\n        <li>Médecin <strong>thésé et en activité</strong>.</li>\n        <li>Médecin <span class=\"kw-clinique\">retraité</span> si <strong>2 conditions</strong> : autorisé par le <span class=\"kw-def\">conseil départemental de l'Ordre</span> <strong>et</strong> impossibilité pour un médecin en activité d'établir le certificat dans un délai raisonnable.</li>\n        <li><span class=\"kw-clinique\">Interne</span> ayant validé <span class=\"kw-chiffre\">2 semestres</span> de sa spécialité (par délégation) ; PADHUE à partir de la <span class=\"kw-chiffre\">2ᵉ année</span> de consolidation.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Les volets du certificat</h4>\n      <table >\n        <thead><tr><th>Volet</th><th>Nominatif ?</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Administratif</strong> (partie supérieure)</td><td><span class=\"kw-alerte\">Nominatif</span> (nom, date de naissance, sexe, adresse)</td><td>Permis d'inhumer + acte de décès ; rempli par le médecin ayant constaté le décès</td></tr>\n          <tr><td><strong>Médical</strong></td><td><span class=\"kw-clinique\">Anonyme</span></td><td>Cause du décès via la <span class=\"kw-def\">CIM-10 de l'OMS</span> → statistiques (<span class=\"kw-def\">CépiDc-Inserm</span>)</td></tr>\n          <tr><td><strong>Médical complémentaire</strong></td><td><span class=\"kw-clinique\">Anonyme</span></td><td>Rempli après examens complémentaires ou <span class=\"kw-clinique\">autopsie</span>, par le médecin qui les a réalisés</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Cases du volet administratif</h4>\n      <ul>\n        <li><strong>Obstacle médico-légal à l'inhumation</strong> (mort violente/suspecte/inexpliquée…).</li>\n        <li><strong>Mise en bière immédiate</strong> (maladie contagieuse) : <span class=\"kw-def\">cercueil hermétique</span> → <em>« Fais Pas le Chaud Ou t'es Cuit »</em> = <span class=\"kw-etio\">Fièvres hémorragiques virales, Peste, Charbon, Orthopoxvirose, Choléra</span> ; <span class=\"kw-def\">cercueil simple</span> → rage, tuberculose.</li>\n        <li>Obstacle aux <span class=\"kw-clinique\">soins de conservation</span> ; obstacle au <span class=\"kw-clinique\">don du corps</span> (<span class=\"kw-ci\">interdit</span> si VIH, VHB, VHC) ; prélèvement pour recherche de cause.</li>\n        <li><strong>Prothèse à pile (pacemaker)</strong> : recherche systématique ; retirée par un <span class=\"kw-clinique\">médecin</span> <strong>ou</strong> un <span class=\"kw-clinique\">thanatopracteur agréé</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Pièges QCM.</strong> Le pacemaker n'est <span class=\"kw-alerte\">pas retiré uniquement par un médecin</span> (aussi le thanatopracteur agréé). Le volet médical est corrigible dans un délai de <strong><span class=\"kw-chiffre\">96h</span></strong> (piège : pas <span class=\"kw-chiffre\">72h</span>). Le volet administratif est transmis à la <span class=\"kw-clinique\">mairie du lieu de décès</span> (puis à l'<span class=\"kw-def\">Insee</span>) — <span class=\"kw-alerte\">jamais à la famille ni au procureur</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 201 — Transplantation d'organe</em></p>","frequence":6},{"id":"13-17","rang":"B","rubrique":"Définition","titre":"Connaître les différents types d’autopsies","contenu":"<table >\n        <thead><tr><th>Critère</th><th>Autopsie médico-légale</th><th>Autopsie médicale / scientifique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cadre</strong></td><td>Ordonnée par le <span class=\"kw-def\">procureur</span> ou un <span class=\"kw-def\">juge d'instruction</span></td><td>Demande du <span class=\"kw-clinique\">corps médical</span> ou de la <span class=\"kw-clinique\">famille</span></td></tr>\n          <tr><td><strong>Consentement</strong></td><td><span class=\"kw-alerte\">Aucun — pas de refus possible</span></td><td>Recherche d'absence d'opposition (registre national de refus, personne de confiance, famille ; consentement écrit si mineur/tutelle)</td></tr>\n          <tr><td><strong>Objectifs</strong></td><td>Cause(s) + circonstances du décès + <span class=\"kw-clinique\">identifier la victime</span></td><td>Diagnostic <span class=\"kw-clinique\">étiologique post-mortem</span> de la pathologie</td></tr>\n          <tr><td><strong>Lieu</strong></td><td>Institut de médecine légale</td><td>Service hospitalier agréé</td></tr>\n          <tr><td><strong>Qui</strong></td><td><span class=\"kw-chiffre\">1 ou 2</span> médecins légistes</td><td><span class=\"kw-clinique\">Anatomopathologiste</span></td></tr>\n          <tr><td><strong>Rapport</strong></td><td>À l'<span class=\"kw-clinique\">autorité requérante</span> (accessible aux ayants droit via cette autorité)</td><td>Intégré au <span class=\"kw-clinique\">dossier médical</span> (accès loi du 4 mars 2002)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Levée de corps médico-légale (rang C, tombé en annale)</h4>\n      <ul>\n        <li>Examen <strong>externe</strong> d'un cadavre, sur <span class=\"kw-def\">réquisition judiciaire</span>, au lieu de découverte du corps.</li>\n        <li>Objectifs : vérifier la <span class=\"kw-clinique\">réalité de la mort</span>, <span class=\"kw-clinique\">dater</span> le décès, vérifier la compatibilité avec la « scène », relever les <span class=\"kw-clinique\">lésions traumatiques</span> et particularités anatomiques.</li>\n        <li><span class=\"kw-ci\">Pas de prélèvement</span> (relève de l'autopsie), <span class=\"kw-ci\">pas d'examen interne</span>, <span class=\"kw-ci\">pas de certificat de décès</span> en cas d'obstacle médico-légal (comptés FAUX en annale).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 201 — Transplantation d'organe</em></p>","frequence":3}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"00e71f85890e","n":13,"o":"13-1","u":"Définition","t":"Connaître les règles générales de rédaction d’un certificat médical","q":"À qui doit être remis un certificat médical et quelles sont les responsabilités du médecin liées à sa rédaction ?","a":"<p>Le certificat médical doit être remis <strong>en mains propres à l'intéressé</strong>. Il est impératif de mentionner en conclusion « établi à la demande de l'intéressé et remis en mains propres » pour préserver le <strong>secret professionnel</strong>.</p><p>Les dérogations légales incluent : mineur → <strong>représentant légal</strong> ; décès → <strong>ayants droit</strong> ; réquisition → <strong>autorités de police</strong>.</p><p>La rédaction d'un certificat engage les responsabilités <strong>pénale, civile et disciplinaire</strong> du médecin s'il est question de certificat de complaisance ou de rapport tendancieux. Les plaintes sont fréquentes lors de séparations ou de divorces.</p>"},{"i":"3b99a47e35a7","n":13,"o":"13-1","u":"Définition","t":"Connaître les règles générales de rédaction d’un certificat médical","q":"Quelles sont les mentions obligatoires et les règles de rédaction des informations sur un certificat médical en France ?","a":"<ul><li><strong>Identité du patient</strong> : S'il est inconnu ou sans pièce d'identité, utiliser la formule « déclarant se nommer ».</li><li><strong>Identité du médecin</strong> : La spécialité n'est pas obligatoire.</li><li><strong>Date exacte</strong> : Ne jamais antidater ou postdater l'examen ou la rédaction du certificat.</li><li><strong>Signature du médecin</strong> : Impérative, jamais celle du patient ni des parents pour un mineur.</li><li><strong>Allégations</strong> (déclarations du patient) : Rédigées au <strong>conditionnel</strong>, par exemple « d'après les déclarations du patient », idéalement en italique. Le médecin n'affirme jamais la responsabilité d'un tiers ni la réalité des faits.</li><li><strong>Constatations</strong> (faits objectifs de l'examen) : Elles sont <strong>exhaustives</strong>. Un examen clinique est obligatoire. Le médecin <strong>n'interprète jamais l'origine des blessures</strong>.</li><li><strong>Diagnostic</strong> : En règle générale, il ne figure pas sur le certificat, sauf cas particuliers.</li></ul>"},{"i":"7ec04c31f28a","n":13,"o":"13-1","u":"Définition","t":"Connaître les règles générales de rédaction d’un certificat médical","q":"Quelle est la définition d'un certificat médical en droit français ?","a":"<p>Le certificat médical est un <strong>document écrit</strong>, rédigé par un médecin à la <strong>demande d'un particulier</strong>, qui vise à constater des <strong>faits d'ordre médical</strong>. Ces faits peuvent influencer directement ou indirectement les intérêts du patient.</p>"},{"i":"0e04d86c7a78","n":13,"o":"13-10","u":"Identifier une urgence","t":"Savoir quelles situations imposent un signalement judiciaire, particulièrement concernant les violences conjugales","q":"Quelles sont les règles concernant le recueil de l'accord de la victime majeure avant d'effectuer un signalement judiciaire ?","a":"<p>Le médecin doit s'efforcer d'obtenir <strong>l'accord</strong> de la victime majeure. En cas d'impossibilité d'obtenir cet accord, il doit l'informer du signalement adressé au Procureur de la République si :</p><ul><li>La victime est <strong>mineure</strong>.</li><li>La victime est une <strong>personne vulnérable</strong>.</li><li>Il existe un <strong>danger imminent</strong> ou une <strong>menace vitale</strong>.</li></ul>"},{"i":"2458d12227e9","n":13,"o":"13-10","u":"Identifier une urgence","t":"Savoir quelles situations imposent un signalement judiciaire, particulièrement concernant les violences conjugales","q":"En dehors des violences conjugales, quelles autres situations imposent un signalement médical selon la loi ?","a":"<p>Les autres situations relevant d'un signalement sont :</p><ul><li>La <strong>maltraitance d'un mineur ou d'une personne vulnérable</strong> (si en danger ou en risque de l'être).</li><li>La <strong>détention d'arme</strong> ou l'intention d'en acquérir si cela représente un danger.</li></ul>"},{"i":"c2d1c5d39d0f","n":13,"o":"13-10","u":"Identifier une urgence","t":"Savoir quelles situations imposent un signalement judiciaire, particulièrement concernant les violences conjugales","q":"Dans quel contexte législatif le signalement par le médecin constitue-t-il une dérogation au secret médical ?","a":"<p>Le signalement est une dérogation légale <strong>facultative</strong> au secret médical, ce qui signifie que le médecin n'a pas l'obligation de signaler, mais a <strong>l'obligation de protéger son patient</strong>. Il devient obligatoire lorsqu'il est le <strong>seul moyen de protéger la victime</strong>.</p>"},{"i":"c88f9487c7a6","n":13,"o":"13-10","u":"Identifier une urgence","t":"Savoir quelles situations imposent un signalement judiciaire, particulièrement concernant les violences conjugales","q":"Selon la loi du 30/07/2020, dans quelles situations un médecin peut-il signaler des violences conjugales au Procureur de la République sans l'accord de la victime majeure ?","a":"<p>Depuis la réforme de l'article 226-14 par la loi du 30/07/2020, le médecin a la possibilité de signaler au Procureur de la République, même sans l'accord de la victime majeure, en cas de <strong>danger immédiat et d'emprise</strong>.</p>"},{"i":"160bb4c711a8","n":13,"o":"13-12","u":"Définition","t":"Connaître la définition de la mort","q":"Comment est estimé le délai post-mortem ?","a":"<p>Le délai post-mortem est estimé par l'étude médico-légale.</p><ul><li>Précocement, il se base sur le <strong>refroidissement</strong>, les <strong>lividités</strong> et la <strong>rigidité</strong>.</li><li>Chez le corps putréfié, il est estimé par l'<strong>entomologie</strong>.</li></ul>"},{"i":"225f2d658bfc","n":13,"o":"13-12","u":"Définition","t":"Connaître la définition de la mort","q":"Deux signes positifs de la mort sont mentionnés pour la constatation réelle et constante du décès. Quels sont-ils ?","a":"<p>Les signes positifs de la mort mentionnés pour la constatation réelle et constante du décès sont la <strong>tache verte abdominale</strong> et les <strong>lividités</strong>.</p>"},{"i":"79513e8ecf79","n":13,"o":"13-12","u":"Définition","t":"Connaître la définition de la mort","q":"Quels sont les pièges à éviter concernant le diagnostic de la mort en QCM ?","a":"<p>Il faut éviter de considérer comme des preuves suffisantes pour affirmer la mort :</p><ul><li>Une <strong>hypothermie à 32°C</strong>.</li><li>L'<strong>absence de pouls radial</strong>.</li><li>L'<strong>absence de réaction à la douleur</strong>.</li></ul><p>Ces éléments ne sont que des signes négatifs de la vie et ne permettent pas à eux seuls de certifier le décès.</p>"},{"i":"885bbf452bc6","n":13,"o":"13-12","u":"Définition","t":"Connaître la définition de la mort","q":"Quelle est la définition médicale de la mort ?","a":"<p>La mort est définie comme la <strong>perte définitive, par une entité vivante, des propriétés de la vie</strong>, entraînant sa destruction.</p>"},{"i":"8d14261c59d9","n":13,"o":"13-12","u":"Définition","t":"Connaître la définition de la mort","q":"Sur quels types de signes repose le diagnostic médical de la mort ?","a":"<p>Le diagnostic médical de la mort repose sur la constatation de <strong>signes négatifs de la vie</strong> (qui ne suffisent pas seuls) et de <strong>signes positifs de la mort</strong>. Le caractère réel et constant de la mort doit être constaté pour l'établissement du certificat de décès.</p>"},{"i":"11c0150f21b6","n":13,"o":"13-13","u":"Définition","t":"Connaître la définition d’une mort suspecte, inhabituelle, violente","q":"La suspicion de maladie à prion est-elle un obstacle médico-légal à l'inhumation ?","a":"<p>Non, la suspicion de <strong>maladie à prion n'est pas un obstacle médico-légal</strong> à l'inhumation.</p>"},{"i":"1adf8d0d0f82","n":13,"o":"13-13","u":"Définition","t":"Connaître la définition d’une mort suspecte, inhabituelle, violente","q":"Quelle est la définition d'une mort violente en médecine légale ?","a":"<p>Une mort violente est un décès qui résulte de l'action d'un <strong>agent extérieur</strong> (physique ou toxique) dans des circonstances <strong>criminelles, suicidaires ou accidentelles</strong>.</p>"},{"i":"691117261660","n":13,"o":"13-13","u":"Définition","t":"Connaître la définition d’une mort suspecte, inhabituelle, violente","q":"La mort inattendue du nourrisson (MIN) est-elle systématiquement un obstacle médico-légal ?","a":"<p>Non, la MIN n'est <strong>pas un obstacle médico-légal systématique</strong>, sauf en cas de refus parental d'autopsie. Il est même recommandé de ne pas cocher l'obstacle pour une MIN.</p>"},{"i":"77c47dc87a2c","n":13,"o":"13-13","u":"Définition","t":"Connaître la définition d’une mort suspecte, inhabituelle, violente","q":"Comment définit-on une mort suspecte en médecine légale ?","a":"<p>Une mort suspecte se définit par l'<strong>impossibilité d'exclure l'intervention d'un tiers</strong> dans le décès.</p>"},{"i":"b2ebc59fd903","n":13,"o":"13-13","u":"Définition","t":"Connaître la définition d’une mort suspecte, inhabituelle, violente","q":"Quelles sont les situations qui imposent de cocher l'obstacle médico-légal à l'inhumation ?","a":"<ul><li>Une <strong>mort violente</strong>.</li><li>Une <strong>mort suspecte</strong>.</li><li>Une <strong>mort subite inhabituelle ou inexpliquée</strong> (sauf MIN).</li><li>Une mort posant un <strong>problème de responsabilité médicale</strong>.</li><li>Un <strong>corps non identifié</strong> (ex: putréfaction, carbonisation).</li></ul>"},{"i":"dda151bc3242","n":13,"o":"13-13","u":"Définition","t":"Connaître la définition d’une mort suspecte, inhabituelle, violente","q":"Qu'est-ce qu'une mort subite inhabituelle ou inexpliquée, et quels sont les cas particuliers en médecine légale ?","a":"<p>Une mort subite inhabituelle ou inexpliquée est un décès qui survient de manière inattendue sans cause évidente. La notion d’«inhabituelle» exclut la <strong>mort inattendue du nourrisson (MIN)</strong>, qui a un régime particulier.</p>"},{"i":"fc58c9e88cc9","n":13,"o":"13-13","u":"Définition","t":"Connaître la définition d’une mort suspecte, inhabituelle, violente","q":"Quelle est la conséquence immédiate pour le médecin lorsqu'un obstacle médico-légal est coché sur le certificat de décès ?","a":"<p>Le médecin a l'<strong>obligation de se mettre en rapport avec le procureur de la République</strong> ou les services de police/gendarmerie. Cela mène à la suspension de toutes les opérations funéraires.</p>"},{"i":"0f02c4e689ea","n":13,"o":"13-14","u":"Diagnostic positif","t":"Savoir diagnostiquer la mort","q":"Quelles sont les particularités des lividités cadavériques en cas d'intoxication au CO, de spoliation sanguine ou de déplacement du corps ?","a":"<ul><li>Des <strong>lividités rouge vif</strong> sont un signe d'<strong>intoxication au CO</strong>.</li><li>Des <strong>lividités pâles</strong> peuvent évoquer une <strong>spoliation sanguine</strong>.</li><li>Une <strong>topographie des lividités incompatible</strong> avec la position du corps suggère un <strong>déplacement du corps</strong> après l'installation des lividités.</li></ul>"},{"i":"1c4eaf50a38a","n":13,"o":"13-14","u":"Diagnostic positif","t":"Savoir diagnostiquer la mort","q":"Quels sont les signes positifs tardifs du décès et leur chronologie approximative ?","a":"<p>Il s'agit des signes de <strong>décomposition/putréfaction</strong> :</p><ul><li><strong>Tache verte abdominale</strong> : 24-48 heures.</li><li><strong>Circulation posthume</strong> : 1 semaine.</li><li><strong>Phlyctènes</strong> : 1-2 semaines.</li><li><strong>Squelettisation</strong> : 12-18 mois.</li></ul><p>Il est important de noter que ces délais comportent d'importantes variations (température, cause du décès) et permettent seulement une estimation, jamais une datation précise.</p>"},{"i":"3cef9fe38bc2","n":13,"o":"13-14","u":"Diagnostic positif","t":"Savoir diagnostiquer la mort","q":"Quels sont les signes positifs précoces permettant la datation du décès et leur chronologie ?","a":"<ul><li>Le <strong>refroidissement cadavérique</strong> : perte de <strong>1°C/heure</strong> après un plateau initial, jusqu'à l'équilibre thermique avec l'environnement.</li><li>Les <strong>lividités</strong> : apparition en <strong>45 minutes</strong>, maximales à <strong>9h30</strong>, disparaissant partiellement après retournement du corps à 11h. Elles sont dues à la transsudation du sang dans les zones déclives.</li><li>La <strong>rigidité cadavérique</strong> : débute <strong>3h</strong> après le décès aux masséters, est maximale à <strong>8h</strong>, et disparaît à <strong>76h</strong>. Elle est due à des liaisons actine-myosine irréversibles par chute de l'ATP.</li></ul>"},{"i":"da04395e2207","n":13,"o":"13-14","u":"Diagnostic positif","t":"Savoir diagnostiquer la mort","q":"Quels sont les signes négatifs de la vie permettant de poser le diagnostic de mort, et leur limite ?","a":"<p>Les signes négatifs de la vie sont :</p><ul><li>L'<strong>abolition de la conscience</strong>, l'<strong>aréflexie</strong> et la <strong>mydriase</strong> (arrêt des fonctions cérébrales).</li><li>L'arrêt de l'<strong>activité respiratoire</strong>.</li><li>L'arrêt de l'<strong>activité cardiovasculaire</strong> (absence de pouls sur les gros troncs artériels).</li></ul><p>Ces signes, pris individuellement, ne suffisent pas à affirmer le décès.</p>"},{"i":"07f04e87b5c5","n":13,"o":"13-16","u":"Définition","t":"Connaître les règles générales de rédaction d'un certificat de décès","q":"Comment est établi le certificat de décès en France et quelles sont les particularités du format papier ?","a":"<p>La <strong>certification électronique</strong> (CertDC / CertDC Mobil) est la règle pour l'établissement du certificat de décès. Le format papier en 4 exemplaires reste <strong>exceptionnel</strong>, réservé aux décès survenus hors établissement de santé ou EHPAD, ou pour des raisons techniques.</p>"},{"i":"1a542a605b27","n":13,"o":"13-16","u":"Définition","t":"Connaître les règles générales de rédaction d'un certificat de décès","q":"Qui est autorisé à établir un certificat de décès en France ?","a":"<p>Peuvent établir un certificat de décès :<ul><li>Un <strong>médecin thésé et en activité</strong>.</li><li>Un <strong>médecin retraité</strong>, sous deux conditions : autorisation du Conseil départemental de l'Ordre et impossibilité pour un médecin en activité d'établir le certificat dans un délai raisonnable.</li><li>Un <strong>interne</strong> ayant validé <strong>2 semestres</strong> de sa spécialité (par délégation).</li><li>Un <strong>PADHUE</strong> à partir de la 2ᵉ année de consolidation.</li></ul></p>"},{"i":"4380243422a2","n":13,"o":"13-16","u":"Définition","t":"Connaître les règles générales de rédaction d'un certificat de décès","q":"Quels sont les différents volets du certificat de décès et leur usage respectif ?","a":"<p>Le certificat de décès comprend trois volets :<ul><li>Le <strong>volet Nominatif (Administratif)</strong> : partie supérieure, renseignant l'identité du défunt, et permettant le permis d'inhumer et l'acte de décès. Il est rempli par le médecin ayant constaté le décès.</li><li>Le <strong>volet Médical Anonyme</strong> : indique la ou les causes du décès selon la CIM-10 de l'OMS, destiné aux statistiques (CépiDc-Inserm).</li><li>Le <strong>volet Médical Complémentaire Anonyme</strong> : rempli, si nécessaire, après examens complémentaires ou autopsie, par le médecin les ayant réalisés.</li></ul></p>"},{"i":"9ccc8a1f02a1","n":13,"o":"13-16","u":"Définition","t":"Connaître les règles générales de rédaction d'un certificat de décès","q":"Quelles sont les informations importantes à renseigner dans les cases spécifiques du volet administratif du certificat de décès ?","a":"<p>Les cases du volet administratif concernent :<ul><li>L'existence d'un <strong>obstacle médico-légal</strong> à l'inhumation (mort violente, suspecte ou inexpliquée).</li><li>La <strong>mise en bière immédiate</strong> en cas de maladie contagieuse :<ul><li><strong>Cercueil hermétique</strong> pour les fièvres hémorragiques virales, Peste, Charbon, Orthopoxvirose, Choléra.</li><li><strong>Cercueil simple</strong> pour la rage, la tuberculose.</li></ul></li><li>L'existence d'un <strong>obstacle aux soins de conservation</strong> ou d'un <strong>obstacle au don du corps</strong> (interdit si VIH, VHB, VHC).</li><li>La nécessité d'un <strong>prélèvement pour recherche de cause</strong>.</li><li>La présence d'une <strong>prothèse à pile (pacemaker)</strong>, qui doit être systématiquement recherchée et retirée par un médecin ou un thanatopracteur agréé.</li></ul></p>"},{"i":"ec944cbda71b","n":13,"o":"13-16","u":"Définition","t":"Connaître les règles générales de rédaction d'un certificat de décès","q":"Quels sont les pièges concernant la rédaction ou la transmission du certificat de décès ?","a":"<p>Les pièges à connaître sont :<ul><li>Le <strong>pacemaker</strong> n'est pas retiré uniquement par un médecin ; un <strong>thanatopracteur agréé</strong> peut aussi le faire.</li><li>Le <strong>volet médical</strong> est corrigible dans un délai de <strong>96 heures</strong> (et non 72 heures).</li><li>Le <strong>volet administratif</strong> est transmis à la <strong>mairie</strong> du lieu de décès (puis à l'Insee) ; il <strong>ne doit jamais être transmis à la famille ni au procureur</strong>.</li></ul></p>"},{"i":"19564fc08da4","n":13,"o":"13-2","u":"Définition","t":"Connaître les différents types de certificats médicaux obligatoires","q":"Le certificat prénuptial et le certificat d'aptitude sportive sont-ils des certificats médicaux obligatoires en France ?","a":"<p>Non, le <strong>certificat prénuptial</strong> et le <strong>certificat d'aptitude sportive</strong> <strong>ne sont plus des certificats médicaux obligatoires</strong>.</p>"},{"i":"47c898caa255","n":13,"o":"13-2","u":"Définition","t":"Connaître les différents types de certificats médicaux obligatoires","q":"Quels sont les principaux types de certificats médicaux obligatoires mentionnés par le Code de la Santé Publique et d'autres législations ?","a":"<ul><li>Certificat de <strong>naissance</strong></li><li>Certificat de <strong>décès</strong></li><li>Certificat de <strong>grossesse</strong></li><li>Certificats pour l'<strong>interruption médicale de grossesse (IMG)</strong> et l'<strong>interruption volontaire de grossesse (IVG)</strong></li><li>Certificats liés à la <strong>législation sociale</strong> (accident du travail, maladie professionnelle)</li><li>Certificats pour les <strong>soins psychiatriques sous contrainte</strong></li><li>Certificats de <strong>vaccination</strong></li><li>Certificats de <strong>suivi de la santé du mineur</strong> (notamment dans les premières années de vie)</li><li>Certificat de « <strong>coups et blessures</strong> » (obligatoire car nécessaire au patient pour faire valoir ses droits)</li></ul>"},{"i":"5d2098fa9f43","n":13,"o":"13-2","u":"Définition","t":"Connaître les différents types de certificats médicaux obligatoires","q":"Dans quel cas un certificat médical est-il légalement considéré comme obligatoire en France ?","a":"<p>Un certificat médical est considéré comme <strong>obligatoire</strong> uniquement lorsque sa rédaction est <strong>prévue par un texte de loi</strong>.</p>"},{"i":"2cee27711689","n":13,"o":"13-6","u":"Epidémiologie","t":"Connaître la prévalence des violences faites aux femmes et plus particulièrement des violences conjugales","q":"Quelle est la prévalence mondiale des violences physiques ou sexuelles faites aux femmes par un partenaire intime ?","a":"<p>Dans le monde, <strong>1 femme sur 4</strong> est victime de violences physiques ou sexuelles commises par un partenaire intime.</p>"},{"i":"6535635699c6","n":13,"o":"13-6","u":"Epidémiologie","t":"Connaître la prévalence des violences faites aux femmes et plus particulièrement des violences conjugales","q":"Quelle est la prévalence des violences conjugales en Europe selon le type de violence ?","a":"<ul><li><strong>22 %</strong> des femmes sont victimes de violences physiques ou sexuelles par un partenaire intime.</li><li><strong>43 %</strong> des femmes sont victimes de violences psychologiques par un partenaire intime.</li><li><strong>1 femme sur 10</strong> (> 15 ans) subit de la cyberviolence.</li></ul>"},{"i":"819449d5c6bf","n":13,"o":"13-6","u":"Epidémiologie","t":"Connaître la prévalence des violences faites aux femmes et plus particulièrement des violences conjugales","q":"Quelle est la proportion de plaintes et de consultations médicales chez les victimes de violences conjugales ?","a":"<p>Il y a un <strong>sous-recours majeur</strong> face aux violences conjugales :</p><ul><li>Seulement <strong>18 %</strong> des victimes déposent plainte.</li><li>Seulement <strong>24 %</strong> des victimes consultent un médecin.</li><li><strong>52 %</strong> des victimes ne font aucune démarche.</li></ul>"},{"i":"82657be024c2","n":13,"o":"13-6","u":"Epidémiologie","t":"Connaître la prévalence des violences faites aux femmes et plus particulièrement des violences conjugales","q":"Quels sont les chiffres clés des violences au sein du couple en France (enquête VIRAGE) sur 12 mois ?","a":"<ul><li><strong>1 %</strong> des femmes victimes de violences physiques par un partenaire.</li><li><strong>20 %</strong> des femmes victimes de violences psychologiques.</li><li><strong>0,1 %</strong> des femmes victimes de violences sexuelles.</li></ul>"},{"i":"1707240f5ac7","n":13,"o":"13-7","u":"Définition","t":"Connaître les particularités des violences faites aux femmes et plus particulièrement des violences conjugales","q":"Selon l'OMS, comment la violence est-elle définie ?","a":"<p>La violence, selon l'<strong>OMS</strong> (Organisation Mondiale de la Santé), est l'usage délibéré, ou la menace d'usage, de la <strong>force physique ou de la puissance</strong> contre soi-même, autrui ou un groupe. Elle entraîne ou risque d'entraîner un <strong>traumatisme, un décès ou un dommage</strong>.</p>"},{"i":"4e54f8253a63","n":13,"o":"13-7","u":"Définition","t":"Connaître les particularités des violences faites aux femmes et plus particulièrement des violences conjugales","q":"Quelle est la définition des violences au sein du couple en France, et quelles sont leurs spécificités ?","a":"<p>La violence au sein du couple est <strong>toute violence</strong> exercée par un <strong>partenaire intime</strong>, que la relation soit présente ou passée (mariage, PACS, concubinage, union libre).</p><p>Ses spécificités sont :</p><ul><li>Elle se déroule dans l'<strong>intimité</strong> (non publique).</li><li>Elle est généralement <strong>chronique</strong> et tend à s'aggraver avec le temps.</li><li>Il existe un <strong>lien émotionnel fort</strong> entre la victime et l'auteur.</li><li>L'<strong>emprise</strong> (ascendance intellectuelle, morale ou économique) crée une <strong>contrainte morale</strong> rendant difficile la sortie de la situation pour la victime.</li></ul>"},{"i":"6d7e6d52e7ac","n":13,"o":"13-7","u":"Définition","t":"Connaître les particularités des violences faites aux femmes et plus particulièrement des violences conjugales","q":"Quels sont les différents types de violence selon l'OMS et quelles sont les formes qu'elle peut prendre ?","a":"<p>La violence peut être:</p><ul><li><strong>Typologie</strong> : Auto-infligée, interpersonnelle (scolaire, travail, domestique) ou collective.</li><li><strong>Formes</strong> : Physique, psychique, sexuelle, économique ou administrative.</li></ul>"},{"i":"738e699bce29","n":13,"o":"13-7","u":"Définition","t":"Connaître les particularités des violences faites aux femmes et plus particulièrement des violences conjugales","q":"Quel est le cycle de la violence élaboré par Walker en 1979 ?","a":"<p>Le cycle de la violence de Walker (1979) comprend quatre phases :</p><ul><li><strong>Tensions</strong> qui s'accumulent.</li><li><strong>Crise ou agression</strong> (passage à l'acte violent).</li><li><strong>Justification</strong> de l'agresseur, souvent par la culpabilisation de la victime.</li><li>Période de « <strong>lune de miel</strong> », où l'agresseur se montre aimant et repentant.</li></ul>"},{"i":"2b590ef0b8bc","n":13,"o":"13-8","u":"Identifier une urgence","t":"Savoir identifier les situations de vulnérabilités, particulièrement concernant les violences conjugales","q":"Comment doit être mené le dépistage des situations de vulnérabilité, notamment liées aux violences conjugales, en médecine générale ?","a":"<p>Le dépistage doit être <strong>systématique</strong> chez tous les patients, quel que soit le motif de consultation et même sans signe d'alerte, selon la recommandation HAS. Il doit se faire lors d'un <strong>entretien en dualité</strong> (seul à seul avec le patient) et être complété par un <strong>examen clinique complet</strong> avec l'accord du patient.</p>"},{"i":"5432042a00ae","n":13,"o":"13-8","u":"Identifier une urgence","t":"Savoir identifier les situations de vulnérabilités, particulièrement concernant les violences conjugales","q":"Comment définir la vulnérabilité d'une personne dans le cadre légal français ?","a":"<p>Selon le Code pénal, la vulnérabilité désigne l'incapacité d'une personne à se protéger en raison de son <strong>âge</strong>, d'une <strong>maladie</strong>, d'une <strong>infirmité</strong>, d'une <strong>déficience physique ou psychique</strong>, ou d'un <strong>état de grossesse</strong>.</p>"},{"i":"ca29fd9eb0c6","n":13,"o":"13-8","u":"Identifier une urgence","t":"Savoir identifier les situations de vulnérabilités, particulièrement concernant les violences conjugales","q":"Quelles sont les situations à évaluer pour apprécier la dangerosité lors de la détection de violences conjugales ?","a":"<p>L'évaluation de la dangerosité (risque de passage à l'acte homicide ou suicide) doit prendre en compte :</p><ul><li>La présence d'<strong>armes au domicile</strong>.</li><li>Des <strong>menaces de mort</strong> explicites.</li><li>Une <strong>tentative de strangulation</strong> antérieure.</li><li>Des problèmes d'<strong>addiction</strong> (alcool, drogues).</li><li>Un comportement de <strong>jalousie ou de contrôle excessif</strong>.</li><li>Une <strong>séparation récente</strong> ou en cours.</li><li>Une <strong>grossesse</strong> ou le <strong>post-partum</strong>.</li><li>Des <strong>enfants témoins</strong> des violences.</li></ul>"},{"i":"dde5e7b1df63","n":13,"o":"13-8","u":"Identifier une urgence","t":"Savoir identifier les situations de vulnérabilités, particulièrement concernant les violences conjugales","q":"Quels sont les signes d'alerte spécifiques de vulnérabilité et de violences à rechercher chez la victime d'une part, et chez le conjoint ou les enfants d'autre part ?","a":"<ul><li><strong>Chez la victime :</strong> <ul><li><strong>Lésions traumatiques répétées</strong> sur des zones de prise/défense, sans explication cohérente.</li><li>Plaintes multiples sans substrat organique évident.</li><li>Mauvaise observance thérapeutique ou retards répétés aux rendez-vous.</li><li>Comportement craintif, isolement, ou refus d'être examinée.</li></ul></li><li><strong>Chez le conjoint :</strong> <ul><li>Accompagnant trop impliqué, répondant à la place du patient.</li><li>Minimalisation des problèmes du patient.</li><li>Propos disqualifiants envers la victime.</li></ul></li><li><strong>Chez les enfants :</strong> <ul><li>Rupture du comportement (repli ou hyperactivité).</li><li>Troubles du sommeil et/ou de l'alimentation.</li><li>Rupture scolaire.</li></ul></li></ul>"}]};